// src/pdfium/ is generated by scripts/pdfium.mjs; these checks fail when it is stale.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { test } from "node:test";
// @ts-expect-error plain .mjs script, no types
import { API, sha256, usedApi, wasmExports } from "../scripts/pdfium.mjs";

const dir = new URL("../src/pdfium/", import.meta.url);
const manifest = JSON.parse(readFileSync(new URL("pdfium.json", dir), "utf8"));
const wasm = readFileSync(new URL("pdfium.wasm", dir));
const regenerate = "run `node scripts/pdfium.mjs`";

test("the trimmed wasm exports every PDFium function the source calls", () => {
	assert.deepEqual(usedApi(), manifest.api, `the source calls a different set of PDFium functions than src/pdfium/ was built for; ${regenerate}`);
	const exports = new Set(wasmExports(wasm));
	for (const name of manifest.api) assert.ok(exports.has(name), `pdfium.wasm does not export ${name}; ${regenerate}`);
	assert.equal(sha256(wasm), manifest.sha256, `src/pdfium/pdfium.wasm was changed by hand; ${regenerate}`);
});

test("the trimmed wasm keeps the Emscripten runtime exports", () => {
	const exports = wasmExports(wasm);
	for (const name of ["memory", "__indirect_function_table", "malloc", "free", "__wasm_call_ctors", "setThrew"]) assert.ok(exports.includes(name), name);
	assert.deepEqual(exports.filter((name: string) => API.test(name)).sort(), manifest.api);
});

test("src/pdfium/ was built from the installed @embedpdf/pdfium", () => {
	const require = createRequire(import.meta.url);
	const source = readFileSync(require.resolve("@embedpdf/pdfium/pdfium.wasm"));
	assert.equal(sha256(source), manifest.sourceSha256, `@embedpdf/pdfium changed; ${regenerate}`);
});

test("the glue wraps every used function", () => {
	const glue = readFileSync(new URL("pdfium.js", dir), "utf8");
	for (const name of manifest.api) assert.match(glue, new RegExp(`^ {4}${name}: \\[`, "m"), name);
	assert.doesNotMatch(glue, /new URL\('pdfium\.wasm'/);
});
